/// <summary>
/// Coc for vendor invoice workflow event handler
/// </summary>
[ExtensionOf(classStr(VendInvoiceHeaderWorkflow))]
final class METVendInvoiceHeaderWorkflow_Extension
{
}

Method.Source:
/// <summary>
/// Activates the vendor invoice workflow.
/// </summary>
public void submit()
{
    next submit();
}

    /// <summary>
    /// Reactivates the vendor invoice header workflow.
    /// </summary>
    public void reSubmit()
    {
        if (METVendParameters::find().EnableMetcashMatchingLogic && !vendInvoiceInfoTable.skipCustomInvoiceMatching() && !vendInvoiceInfoTable.isLandedCostEnabled())
        {
            boolean metValid;
            str     metMessage;

            [metValid, metMessage] = VendInvoiceHeaderWorkflow::metValidateSubmissionForInvoiceMatching(vendInvoiceInfoTable);

            if (!metValid)
            {
                throw error(metMessage);
            }
        }

        next reSubmit();
    }

    /// <summary>
    /// validates if the vendor invoice can be submitted/resubmitted to workflow according to invoice matching requirements
    /// </summary>
    /// <param name = "_metVendInvoiceInfoTable">Vendor invoice</param>
    /// <returns>Container statement if valid and error message</returns>
    public static container metValidateSubmissionForInvoiceMatching(VendInvoiceInfoTable _metVendInvoiceInfoTable)
    {
        boolean     metValid = true;
        str         metMessage = '';

        if (!_metVendInvoiceInfoTable.purchTable().isInterCompanyOrder() && !_metVendInvoiceInfoTable.METClaimInvoice)
        {
            // Bug 350958: E2E: SO-0237 - Wrong amount posting to In-Tolerance Variance Line Unit Price & Actual GST
            // Reread the record in case user opened the PVI while in the workflow.
            _metVendInvoiceInfoTable.reread();

            if (_metVendInvoiceInfoTable.displayInvoiceTotal() != 0 && !_metVendInvoiceInfoTable.MetImportAmount)
            {
                metValid = false;
                metMessage = strFmt("@MET:NoInvAmtNoGST" + ' %1', _metVendInvoiceInfoTable.Num);
            }
            else if (_metVendInvoiceInfoTable.displayMetMatchStatus() == METMatchStatus::Fail)
            {
                metValid = false;
                metMessage = strFmt("@MET:MetMatchStatusFail" + ' %1', _metVendInvoiceInfoTable.Num);
            }
            
            metValid = metValid && _metVendInvoiceInfoTable.metCheckInvoice();

        }

        return [metValid, metMessage];
    }

    /// <summary>
    /// Activates the vendor invoice workflow.
    /// </summary>
    /// <param name="_vendInvoiceInfoTable">
    /// The <c>VendInvoiceInfoTable</c> table.
    /// </param>
    /// <param name="_workflowComment">
    /// The submission comment.
    /// </param>
    /// <remarks>
    /// This method starts the workflow configuration by calling the <c>ActivateWorkflowTemplate</c> method
    /// on the <c>Workflow</c> class that has information about the vendor invoice record.
    /// </remarks>
    public static void submitToWorkflow(VendInvoiceInfoTable _vendInvoiceInfoTable, WorkflowComment _workflowComment)
    {
        if (METVendParameters::find().EnableMetcashMatchingLogic && !_vendInvoiceInfoTable.skipCustomInvoiceMatching() && !_vendInvoiceInfoTable.isLandedCostEnabled())
        {
            boolean metValid;
            str     metMessage;
            Amount  calculatedGST = 0;
            Amount  metTotalMarkupTax, metTotalMarkupAmount;
            Amount  metTotalLineTax, metTotalLineAmount;

            [metValid, metMessage] = VendInvoiceHeaderWorkflow::metValidateSubmissionForInvoiceMatching(_vendInvoiceInfoTable);

            [metTotalMarkupAmount, metTotalMarkupTax] = _vendInvoiceInfoTable.metMarkupTotals();
            [metTotalLineAmount, metTotalLineTax]     = _vendInvoiceInfoTable.metLineAmounts();

            calculatedGST = abs(metTotalLineTax - metTotalMarkupTax);

            if (_vendInvoiceInfoTable.MetImportGST == 0 && calculatedGST != 0)
            {
                warning(strFmt("@MET:VendGSTAndCalculatedGSTWarning", calculatedGST));
            }

            if (!metValid)
            {
                throw error(metMessage);
            }
        }


        next submitToWorkflow(_vendInvoiceInfoTable, _workflowComment);
    }
